import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Tabs, Tab, Avatar, Chip, CircularProgress,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow, IconButton,
  Grid, Card, CardContent,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EventBusyIcon from '@mui/icons-material/EventBusy';
import PersonOffIcon from '@mui/icons-material/PersonOff';
import PaymentsIcon from '@mui/icons-material/Payments';
import CardGiftcardIcon from '@mui/icons-material/CardGiftcard';
import MoneyOffIcon from '@mui/icons-material/MoneyOff';
import { formatPersianNumber } from '../core/utils/numberUtils';
import { toJalali } from '../core/utils/dateUtils';
import LeaveForm from '../modules/dataEntry/LeaveForm';
import AbsenceForm from '../modules/dataEntry/AbsenceForm';
import SalaryForm from '../modules/dataEntry/SalaryForm';
import SalaryList from '../modules/dataEntry/SalaryList';
import BenefitForm from '../modules/dataEntry/BenefitForm';
import DeductionForm from '../modules/dataEntry/DeductionForm';
import { TRANSACTION_TYPES, SUB_TYPE_LABELS } from '../modules/dataEntry/config';

const TYPE_META = {
  leave: { icon: <EventBusyIcon />, color: '#6366f1' },
  absence: { icon: <PersonOffIcon />, color: '#ef4444' },
  salary: { icon: <PaymentsIcon />, color: '#f59e0b' },
  benefit: { icon: <CardGiftcardIcon />, color: '#10b981' },
  deduction: { icon: <MoneyOffIcon />, color: '#8b5cf6' },
};

const TABS = [
  { key: 'leave', label: 'مرخصی', icon: <EventBusyIcon /> },
  { key: 'absence', label: 'غیبت', icon: <PersonOffIcon /> },
  { key: 'salary', label: 'حقوق', icon: <PaymentsIcon /> },
  { key: 'benefit', label: 'مزایا', icon: <CardGiftcardIcon /> },
  { key: 'deduction', label: 'کسورات', icon: <MoneyOffIcon /> },
];

const DataEntryPage = () => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [tab, setTab] = useState(0);

  const { data: transactions, isLoading } = useQuery({
    queryKey: ['transactions'],
    queryFn: () => axiosInstance.get('/transactions/').then(r => r.data),
  });

  const items = Array.isArray(transactions) ? transactions : transactions?.results || [];

  const handleDelete = async (id) => {
    await axiosInstance.delete(`/transactions/${id}/`);
    queryClient.invalidateQueries({ queryKey: ['transactions'] });
  };

  const renderForm = () => {
    const onSuccess = () => {
      queryClient.invalidateQueries({ queryKey: ['transactions'] });
      queryClient.invalidateQueries({ queryKey: ['employee-transactions'] });
    };
    switch (TABS[tab].key) {
      case 'leave': return <LeaveForm onSuccess={onSuccess} />;
      case 'absence': return <AbsenceForm onSuccess={onSuccess} />;
      case 'salary': return (
        <Box>
          <SalaryForm onSuccess={onSuccess} />
          <Box sx={{ mt: 3 }}>
            <SalaryList />
          </Box>
        </Box>
      );
      case 'benefit': return <BenefitForm onSuccess={onSuccess} />;
      case 'deduction': return <DeductionForm onSuccess={onSuccess} />;
      default: return null;
    }
  };

  return (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h4" fontWeight={800}>ورود اطلاعات</Typography>
        <Typography variant="body2" color="textSecondary">
          ثبت تخصصی مرخصی، غیبت، حقوق، مزایا و کسورات پرسنل
        </Typography>
      </Box>

      {/* Tabs */}
      <Paper sx={{ mb: 3, overflow: 'hidden' }}>
        <Tabs
          value={tab}
          onChange={(e, v) => setTab(v)}
          variant="scrollable"
          scrollButtons="auto"
          sx={{ borderBottom: 1, borderColor: 'divider', px: 2, bgcolor: 'rgba(255,255,255,0.5)' }}
        >
          {TABS.map((titem, i) => (
            <Tab
              key={titem.key}
              icon={titem.icon}
              iconPosition="start"
              label={titem.label}
              sx={{ color: tab === i ? TYPE_META[titem.key].color : undefined }}
            />
          ))}
        </Tabs>

        <Box sx={{ p: 3 }}>
          {renderForm()}
        </Box>
      </Paper>

      {/* Recent transactions */}
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" fontWeight={700} sx={{ mb: 2 }}>تراکنش‌های اخیر</Typography>
        {isLoading ? (
          <Box sx={{ p: 4, textAlign: 'center' }}><CircularProgress size={24} /></Box>
        ) : !items.length ? (
          <Typography color="textSecondary" sx={{ textAlign: 'center', py: 3 }}>تراکنشی ثبت نشده است</Typography>
        ) : (
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: 700 }}>پرسنل</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>نوع</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>زیرنوع</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>مبلغ (ریال)</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>مقدار</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>تاریخ</TableCell>
                  <TableCell width={50}></TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {items.slice(0, 30).map(tx => {
                  const meta = TYPE_META[tx.transaction_type] || { color: '#999', icon: null };
                  return (
                    <TableRow key={tx.id} hover>
                      <TableCell>{tx.employee_name}</TableCell>
                      <TableCell>
                        <Chip size="small" icon={meta.icon ? React.cloneElement(meta.icon, { sx: { fontSize: 14, color: meta.color } }) : undefined}
                          label={tx.transaction_type_display} variant="outlined" sx={{ color: meta.color, borderColor: meta.color }} />
                      </TableCell>
                      <TableCell>{SUB_TYPE_LABELS[tx.sub_type] || '—'}</TableCell>
                      <TableCell>{tx.amount ? formatPersianNumber(tx.amount) : '—'}</TableCell>
                      <TableCell>{tx.quantity ? formatPersianNumber(tx.quantity) : '—'}</TableCell>
                      <TableCell>{toJalali(tx.date)}</TableCell>
                      <TableCell>
                        <IconButton size="small" color="error" onClick={() => handleDelete(tx.id)}>
                          <DeleteIcon fontSize="small" />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </Paper>
    </Box>
  );
};

export default DataEntryPage;
